pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post_residuals (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for opening new bins: Only do so if the current bin creates a very poor fit
    // or if we have many empty/near-empty bins already.
    if is_new_bin {
        score += 25.0; // Base cost of opening a new container
        score -= (open_bins_count as f64) * 0.5; // If we have many bins, the penalty for a new one is diluted
    }

    // Lookahead logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Adaptivity: If we are near the end of the stream, prioritize packing tightly to finish.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // Fragmentation avoidance: Penalize bins that leave very small, unusable residuals (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state awareness: If we have many fitting bins, be more selective.
    // Discourage placing in a bin that is significantly above the mean residual.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // Urgency: If this is the only bin that can fit the item, prioritize it heavily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals that are too small to fit common items)
    // Small residuals < 10 are often unusable; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class Logic: Favor filling bins to specific "harmonic" thresholds (e.g., 50, 33, 25)
    // Reward residuals that land near multiples of 25 (e.g., 0, 25, 50)
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Fitting Density: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should be careful not to waste it if the residual is poor.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 10.0;
    }

    // 5. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), only pick it if
    // the current packing situation is dire.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open already or if the item is large.
        if open_bins_count > 5 || item_size > 70 {
            score = 15.0; // Base cost to open a new bin
        } else {
            score = 100.0; // Heavily discourage opening new bins early
        }
    }

    // 6. Global pressure: As the stream progresses, prioritize closing bins (lower residual)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep space tight.
    // If we are opening a new bin, penalize based on the current average waste.
    if bin_residual == bin_capacity {
        score = mean_residual * 1.5;
    }

    // 2. Harmonic Lookahead: If the next item can fit in the post_residual,
    // prioritize this bin to preserve bin count.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fragmentation Penalty: Penalize post_residuals that are too small to fit 
    // common small items (e.g., < 10) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic Alignment: Use modulo arithmetic to favor values that leave
    // space for specific "classes" of items (e.g., 20, 25, 50).
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
        score += harmonic_penalty;
    }

    // 5. Pressure scaling: As we approach the end of the stream, 
    // be more aggressive in filling bins (lower the score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Last-Chance Logic: If this is the only bin that can fit the item,
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit)
    // We use a quadratic term to penalize bins that leave too much empty space disproportionately.
    let mut score = post * post / 100.0;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // strongly reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic density pressure: As the stream progresses, prioritize closing bins
    // that are near-full. If fitting_bins_count is low, we are running out of options;
    // penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream
        // and decreases if we have plenty of open bins already.
        score += 45.0 + (progress * 20.0) - (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that bring the residual closer to the mean_residual of all bins,
        // promoting uniform packing density across the bin set.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Final scaling: penalize creating "dead zones" (very small residuals that 
    // are unlikely to fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is often "unusable" 
    // because items are >= 10. Heavily penalize these "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this placement to keep bins tightly packed.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // make it highly attractive to avoid forced new-bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better 
    // than the mean residual, slightly reward it to favor Best-Fit behavior.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Penalize small residuals (fragmentation) quadratically to promote Best-Fit behavior
    // The penalty is dampened as we approach the end of the stream to favor bin closing
    let fragmentation_penalty = (100.0 - post_res_f).powi(2) * (1.0 - 0.2 * progress);

    // Favor bins that can accommodate the next item (lookahead coupling)
    // If next_item_size > post_residual, we penalize this bin for creating a dead gap
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            lookahead_penalty = (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Discourage opening new bins early in the stream, but allow it if current bins are poor
    let mut new_bin_penalty = 0.0;
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is weighted by how many existing bins 
        // are already poorly utilized (high mean_residual)
        new_bin_penalty = 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // Final score: lower is better. 
    // We favor smaller post_residuals (tighter packing) but balance with lookahead efficiency.
    let score = post_res_f + fragmentation_penalty + lookahead_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to encourage tight packing.
    // We add a quadratic penalty for the post_residual to favor smaller remaining space.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If post_residual can fit the next item, heavily reward this bin.
    // This reduces fragmentation by creating "perfect" fits for the upcoming item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 15.0;
        score -= (post_residual - next_item_size) as f64 * 2.0;
    }

    // 3. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current fitting bins are very poor matches.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by the number of bins already open
        // to prevent explosion of bins in mid-to-late stages.
        score += 150.0 - (open_bins_count as f64 * 0.5);
    } else {
        // 4. Distributional Balancing: Favor bins that stay close to the mean_residual
        // to prevent creating extreme outliers in bin fullness.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive
    // about utilizing existing open bins (lower the penalty for "bad" fits).
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - (progress * 0.3);

    score
}
